/* =========================================================================
   PWA support for Card Lobby: serves the web manifest and app icons so the
   page can be installed via "Add to Home Screen". Icons are embedded as
   base64 so there are no binary files to upload — just this module.
   ========================================================================= */
const MANIFEST = "{\"name\": \"Card Lobby\", \"short_name\": \"Card Lobby\", \"description\": \"Real-time multiplayer card table \\u2014 poker, blackjack, Go Fish and more.\", \"start_url\": \"/\", \"scope\": \"/\", \"display\": \"standalone\", \"orientation\": \"portrait\", \"background_color\": \"#08291e\", \"theme_color\": \"#0e3b2b\", \"icons\": [{\"src\": \"/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any\"}, {\"src\": \"/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any\"}, {\"src\": \"/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"maskable\"}]}";
const ICONS = {
  "/icon-192.png": "",
  "/icon-512.png": "",
  "/apple-touch-icon.png": "",
  "/favicon.png": "",
};

function mountPWA(app) {
  app.get("/manifest.webmanifest", (_req, res) => {
    res.type("application/manifest+json").set("Cache-Control", "public, max-age=86400").send(MANIFEST);
  });
  for (const path of Object.keys(ICONS)) {
    const buf = Buffer.from(ICONS[path], "base64");
    app.get(path, (_req, res) => { res.type("png").set("Cache-Control", "public, max-age=604800").send(buf); });
  }
}
module.exports = { mountPWA };
